        const nc = c + len + turn;
        const ns = nb * 5 + d;
        if (nc < dist[ns]) {
          dist[ns] = nc;
          prev[ns] = st;
          heap.push(nc, ns);
        }
      }
    }
    return null;
  };

  const srcNodes = srcStarts.map(nodeOf);
  const tgtNodes = new Set(tgtGoals.map(nodeOf));
