        heap.push(0, st);
      }
    }
    while (heap.size) {
      const [c, st] = heap.pop();
      if (c > dist[st]) continue;
      const node = Math.floor(st / 5);
      const dir = st % 5;
      if (goalNodes.has(node)) {
        const nodes = [];
        for (let cur = st; cur !== -1; cur = prev[cur]) nodes.push(Math.floor(cur / 5));
