        );
        break;
      case 'line':
        body.push(
          `<line${id} x1="${n(v.x)}" y1="${n(v.y)}" x2="${n(v.x + v.width)}" y2="${n(v.y + v.height)}" stroke="${escapeXml(st.stroke ?? '#000000')}" stroke-width="${n(st.strokeWidth ?? 1)}"${tr} />`,
