    }
    const fresh = [];
    for (const op of ops) {
      if (this.seen.has(op.id)) continue;
      this.seen.add(op.id);
      fresh.push(op);
    }
    if (fresh.length === 0) return fresh;
    this.doc.receive(fresh);
    this.ops.push(...fresh);
    fs.appendFileSync(this.logFile, fresh.map((o) => JSON.stringify(o) + '\n').join(''));
