        return sendJson(res, 200, { ...live.doc.toJSON(), ...docSummary(meta, role), members: meta.members });
      }
      if (method === 'DELETE') {
        const { meta } = loadDoc(id, user, ['owner']);
        store.deleteDoc(meta.id);
