      },
      onClose: () => {
        live.sockets.delete(conn);
        wsByDoc.get(meta.id)?.delete(conn);
      },
    });
    live.sockets.add(conn);
    if (!wsByDoc.has(meta.id)) wsByDoc.set(meta.id, new Set());
    wsByDoc.get(meta.id).add(conn);
    conn.send({ type: 'hello', seq: live.seq, role });
  });

  return server;
}

