* { box-sizing: border-box; }
html, body { margin: 0; height: 100%; font: 14px system-ui, sans-serif; color: #222; background: #f4f5f7; }
.hidden { display: none !important; }
.screen { height: 100%; display: flex; flex-direction: column; }
#login { align-items: center; justify-content: center; gap: 12px; }
#login form { display: flex; flex-direction: column; gap: 8px; width: 260px; }
.error { color: #b00020; min-height: 1em; }
.bar { display: flex; align-items: center; gap: 6px; padding: 6px 10px; background: #fff; border-bottom: 1px solid #ddd; flex-wrap: wrap; }
.grow { flex: 1; }
.sep { width: 1px; height: 22px; background: #ccc; margin: 0 4px; }
button, select, input { font: inherit; }
button { padding: 3px 8px; border: 1px solid #bbb; background: #fff; border-radius: 4px; cursor: pointer; }
button.active { background: #2b6cb0; color: #fff; border-color: #2b6cb0; }
.dash-body { padding: 16px; display: flex; flex-direction: column; gap: 12px; max-width: 640px; }
#docList li { padding: 6px 0; border-bottom: 1px solid #e3e3e3; display: flex; gap: 8px; align-items: center; }
#docList a { color: #2b6cb0; text-decoration: none; }
.main { flex: 1; display: flex; min-height: 0; }
.side { width: 220px; overflow: auto; background: #fff; padding: 8px; border-right: 1px solid #ddd; }
.side.right { border-right: none; border-left: 1px solid #ddd; width: 240px; }
.side h3 { font-size: 13px; margin: 8px 0 4px; display: flex; gap: 6px; align-items: center; }
.side ul { list-style: none; margin: 0; padding: 0; }
.side li { padding: 3px 0; display: flex; gap: 6px; align-items: center; flex-wrap: wrap; }
#props label { display: flex; justify-content: space-between; margin: 4px 0; gap: 6px; }
#props input[type=text], #props input[type=number] { width: 110px; }
.stage { flex: 1; position: relative; overflow: hidden; background: #fafafa; }
#canvas { width: 100%; height: 100%; display: block; cursor: default; user-select: none; }
#minimap { position: absolute; right: 10px; bottom: 10px; background: #fff; border: 1px solid #bbb; }
.pill { padding: 2px 8px; border-radius: 10px; background: #ddd; font-size: 12px; }
.pill.on { background: #c6f6d5; }
.pill.off { background: #fed7d7; }
#status { color: #555; }
#comments li { flex-direction: column; align-items: flex-start; border-bottom: 1px solid #eee; padding: 4px 0; }
#comments li.resolved { opacity: 0.5; }
.doc-title { font-weight: 600; margin-right: 6px; }

