  assert.equal(a.style.fill, '#dae8fc');
  assert.equal(d.get('b').type, 'diamond');
  const c = d.get('e');
  assert.equal(c.type, 'connector');
  assert.equal(c.routing, 'orthogonal');
  assert.equal(c.label, 'yes');
  assert.deepEqual(c.waypoints, [[200, 200]]);
